[metadata] {"filePath": "/workspace/repo/src/vs/workbench/contrib/chat/common/promptSyntax/computeAutomaticInstructions.ts", "oldString": "	private async _addAgentInstructions(variables: ChatRequestVariableSet, telemetryEvent: InstructionsCollectionEvent, token: CancellationToken): Promise<void> {", "newString": "	/**
	 * When {@link PromptsConfig.SEARCH_ROOT_REPO_CUSTOMIZATIONS} is enabled, discovers customization
	 * files (CLAUDE.md, .claude/CLAUDE.md, .github/copilot-instructions.md and AGENTS.md) located in
	 * the parent directories above the workspace root folder(s) and adds them as instruction context.
	 * This supports monorepo layouts where a workspace folder is nested inside a parent repository.
	 */
	private async _addRootRepositoryCustomizations(variables: ChatRequestVariableSet, telemetryEvent: InstructionsCollectionEvent, token: CancellationToken): Promise<void> {
		const searchRootRepoCustomizations = this._configurationService.getValue(PromptsConfig.SEARCH_ROOT_REPO_CUSTOMIZATIONS);
		if (searchRootRepoCustomizations !== true) {
			return;
		}

		// Relative paths of the customization files to look for in each ancestor directory.
		const customizationPaths = [
			CLAUDE_MD_FILENAME, // CLAUDE.md
			`${CLAUDE_CONFIG_FOLDER}/${CLAUDE_MD_FILENAME}`, // .claude/CLAUDE.md
			`.github/${COPILOT_CUSTOM_INSTRUCTIONS_FILENAME}`, // .github/copilot-instructions.md
			AGENT_MD_FILENAME, // AGENTS.md
		];

		const seenFolders = new ResourceSet();
		for (const folder of this._workspaceService.getWorkspace().folders) {
			let current = dirname(folder.uri);
			while (!seenFolders.has(current)) {
				seenFolders.add(current);

				for (const relativePath of customizationPaths) {
					if (token.isCancellationRequested) {
						return;
					}
					const fileUri = joinPath(current, relativePath);
					try {
						const stat = await this._fileService.stat(fileUri);
						if (stat.isFile) {
							variables.add(toPromptFileVariableEntry(fileUri, PromptFileVariableKind.Instruction, undefined, true));
							telemetryEvent.agentInstructionsCount++;
							this._logService.trace(`[InstructionsContextComputer] Root repository customization file added: ${fileUri.toString()}`);
						}
					} catch (error) {
						// file does not exist or cannot be read, ignore
					}
				}

				const parent = dirname(current);
				if (isEqual(parent, current)) {
					// reached the filesystem root
					break;
				}
				current = parent;
			}
		}
	}

